//! 🧳️ One original-bound flat record owner composes typed field receiving, validation, assembly and cancellation.
use super::{NativeFlatRecord,NativeRecordSource};
use crate::{NativeDecodeControl,Number,RetirementDemand,ValueError,ValueRefusalKind,native_decoding::owned::{NativeReceiver,NativeIntrinsicSharedField},retirement::shared::sealed::SealedShared,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
/// 🏗️ Record fields and every source alias remain owned until the separately funded final transfer or closure.
pub struct NativeFlatRecordReceiver<I:NativeRecordSource,R:NativeFlatRecord<T,N>,const T:usize,const N:usize>{binding:Option<RetainedCloneBinding>,fields:[NativeIntrinsicSharedField<String>;T],positions:[Option<usize>;T],texts:ManuallyDrop<[Option<SealedShared<String>>;T]>,numbers:[Option<Number>;N],output:ManuallyDrop<Option<R>>,retirement:RetainedCloneClose,scan:usize,field:usize,phase:u8,closing:bool,input:std::marker::PhantomData<fn()->I>}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native flat record requires exactly its declared original fields and typed parts")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<I:NativeRecordSource,R:NativeFlatRecord<T,N>,const T:usize,const N:usize> NativeFlatRecordReceiver<I,R,T,N>{
 pub fn birth_demand()->RetirementDemand{fixed(size_of::<Self>())}
 pub fn begin(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(invalid());}Ok((Self{binding:None,fields:std::array::from_fn(|_|Default::default()),positions:[None;T],texts:ManuallyDrop::new(std::array::from_fn(|_|None)),numbers:[None;N],output:ManuallyDrop::new(None),retirement:Default::default(),scan:0,field:0,phase:0,closing:false,input:std::marker::PhantomData},receipt(d)))}
 fn text_source<'a>(&self,original:RetainedCloneRef<'a,I>,field:usize)->Result<RetainedCloneRef<'a,String>,ValueError>{let index=self.positions[field].ok_or_else(invalid)?;Ok(original.project(index,move|input|input.text_field(index).expect("original validated immutable text field")))}
 fn parts(&self)->Result<([&str;T],[Number;N]),ValueError>{if self.texts.iter().any(Option::is_none)||self.numbers.iter().any(Option::is_none){return Err(invalid());}Ok((std::array::from_fn(|index|self.texts[index].as_ref().unwrap().as_str()),std::array::from_fn(|index|self.numbers[index].unwrap())))}
}
impl<I:NativeRecordSource,R:NativeFlatRecord<T,N>,const T:usize,const N:usize> NativeReceiver<I,R> for NativeFlatRecordReceiver<I,R,T,N>{
 fn demands(&self,original:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{
  if self.closing||self.phase>=6{return Err(invalid());}original.check_binding(&self.binding)?;
  match self.phase{0=>Ok(fixed(original.binding_copy_bytes()+size_of::<u8>())),1=>Ok(fixed(R::TEXT_FIELDS.iter().chain(R::NUMBER_FIELDS.iter()).map(|field|field.name.len()).sum::<usize>()+3*size_of::<usize>()+size_of::<Option<Number>>()+size_of::<u8>())),2=>{let mut d=self.fields[self.field].demands(self.text_source(original,self.field)?,body)?;d.copy_bytes+=size_of::<usize>();Ok(d)},3=>{let mut d=self.fields[self.field].take_demand()?;d.copy_bytes+=size_of::<SealedShared<String>>()+size_of::<usize>();Ok(d)},4=>{let(texts,numbers)=self.parts()?;let mut d=R::validation_demand(texts,numbers);d.copy_bytes+=size_of::<u8>()+size_of::<[&str;T]>()+size_of::<[Number;N]>();d.depth=d.depth.max(1);Ok(d)},5=>Ok(fixed(3*size_of::<R>()+size_of::<[Option<SealedShared<String>>;T]>()+size_of::<u8>())),_=>Err(invalid())}
 }
 fn advance(&mut self,original:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
  let d=self.demands(original,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}control.checkpoint()?;
  match self.phase{
   0=>{let mut p=original.bind(&mut self.binding,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<u8>(),..g})?.ok_or_else(invalid)?;self.phase=1;p.copied_bytes+=size_of::<u8>();return Ok(RetainedCloneStep::Progress(p));},
   1=>{if original.get().field_count()?!=T+N{return Err(invalid());}if T+N==0{self.phase=4;return Ok(RetainedCloneStep::Progress(receipt(d)));}if self.scan>=T+N{return Err(invalid());}let input=original.get();let key=input.field_key(self.scan)?;let text=R::TEXT_FIELDS.iter().position(|field|field.matches(key));if let Some(field)=text{if self.positions[field].is_some(){return Err(invalid());}input.text_field(self.scan)?;self.positions[field]=Some(self.scan);}else{let field=R::NUMBER_FIELDS.iter().position(|field|field.matches(key)).ok_or_else(invalid)?;if self.numbers[field].is_some(){return Err(invalid());}self.numbers[field]=Some(input.number_field(self.scan)?);}self.scan+=1;if self.scan==T+N{self.phase=if T==0{4}else{2};}},
   2=>{let source=self.text_source(original,self.field)?;let mut p=self.fields[self.field].advance(source,control,body,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<usize>(),..g})?.progress();if self.fields[self.field].ready(){self.field+=1;if self.field==T{self.field=0;self.phase=3;}}p.copied_bytes+=size_of::<usize>();return Ok(RetainedCloneStep::Progress(p));},
   3=>{let overhead=size_of::<SealedShared<String>>()+size_of::<usize>();let(value,mut p)=self.fields[self.field].take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-overhead,..g})?.ok_or_else(invalid)?;self.texts[self.field]=Some(value);self.field+=1;if self.field==T{self.phase=4;}p.copied_bytes+=overhead;return Ok(RetainedCloneStep::Progress(p));},
   4=>{let(texts,numbers)=self.parts()?;R::validate_parts(texts,numbers).map_err(|error|error.with_retained_progress(receipt(d)))?;self.phase=5;},
   5=>{self.parts()?;let texts=std::array::from_fn(|index|self.texts[index].take().unwrap());let numbers=std::array::from_fn(|index|self.numbers[index].unwrap());*self.output=Some(R::from_parts(texts,numbers));self.phase=6;},_=>return Err(invalid())
  }Ok(if self.phase==6{RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})
 }
 fn output_ready(&self)->bool{!self.closing&&self.phase==6&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(fixed(2*size_of::<R>()+size_of::<u8>()))}
 fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(R,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}self.phase=7;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))}
 fn begin_close(&mut self){self.closing=true;for field in &mut self.fields{field.begin_close();}}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}for field in &self.fields{if !field.terminal_is_empty(){return field.close_demands(body);}}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<R>(false,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<R>(true,&None,body);}if self.texts.iter().any(Option::is_some){return self.retirement.next_owner_demands::<SealedShared<String>>(true,&None,body);}RetainedCloneBinding::demands(&self.binding,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}for field in &mut self.fields{if !field.terminal_is_empty(){return field.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if let Some(s)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}for text in self.texts.iter_mut(){if let Some(s)=self.retirement.begin_granted(text,g)?{return Ok(RetainedCloneStep::Progress(s.progress()));}}RetainedCloneBinding::close_one(&mut self.binding,g)}
 fn terminal_is_empty(&self)->bool{self.fields.iter().all(NativeIntrinsicSharedField::terminal_is_empty)&&self.texts.iter().all(Option::is_none)&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl<I:NativeRecordSource,R:NativeFlatRecord<T,N>,const T:usize,const N:usize> Drop for NativeFlatRecordReceiver<I,R,T,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native flat record retains original receiving custody");}}
